// Generated by `just generate` from `src/plugins/dcc-plugin-you-should-know/slices/notice/lab/notice.test.ts`. Edit the source and run `just generate`.
// Lab tests of the `notice` slice: the check of the first changing call of a turn, the band above the prompt, the heads-up note, and the calls that get no notice.
// The hooks sit above the stubs of the engine: the stubs answer the verdict, the model calls, and the clock, and record each toast.
// The band is drawn by `$.ui.mount`, and its state is read by `$.state.get`, as the plugin itself reads them.
// No model call goes out, and no Claude Code session runs.

import type {
  ModelCompleteResult,
  ModelForkResult,
  On,
  ToolCheckDecision,
} from "claude-code";
import { type Engine, expect, mock, test } from "claude-code/testing";

const PLUGIN = "dcc-plugin-you-should-know";

const NO_USAGE = {
  input_tokens: 0,
  output_tokens: 0,
  cache_read_input_tokens: 0,
  cache_creation_input_tokens: 0,
};

const answered = (text: string) => ({
  isAnswered: true as const,
  text,
  usage: NO_USAGE,
});

const failed = (status: number) => ({
  isAnswered: false as const,
  reason: "api-error" as const,
  status,
  error: status === 429 ? ("rate_limit" as const) : ("server_error" as const),
  usage: NO_USAGE,
});

/** The world of one test: the answers of the model calls, in order, and the verdict of each call. */
type World = {
  readonly complete?: readonly ModelCompleteResult[];
  readonly fork?: readonly (ModelForkResult | "never")[];
  readonly decision?: ToolCheckDecision;
};

type Clock = ReturnType<typeof mock.clock>;

/** What the stubs saw: the prompts of each model call, each toast that the plugin raised, which must stay empty, and each text put in the prompt box. */
type Seen = {
  complete: string[];
  fork: string[];
  toasts: string[];
  fills: string[];
};

/** Stubs for one test. A model call past the end of its list answers `NONE`. */
const setup = (on: On, world: World = {}) => {
  const seen: Seen = { complete: [], fork: [], toasts: [], fills: [] };
  const clock = mock.clock(on);
  on("turn.start", (_$, e) => ({ turnId: e.turnId }));
  on("tool.check", () => ({ decision: world.decision ?? "allow" }));
  on("tool.call", () => ({ result: "ok", context: ["other"] }));
  // The bottom of the render chain: an empty box, so that a band the plugin does not draw shows nothing.
  on("ui.render", ($, e) => $.ui.resolve(e).Box({ children: [] }));
  on("model.complete", (_$, e) => {
    const reply = world.complete?.[seen.complete.length] ?? answered("NONE");
    seen.complete.push(e.prompt);
    return { value: reply };
  });
  on("model.fork", (_$, e) => {
    const reply = world.fork?.[seen.fork.length] ?? answered("NONE");
    seen.fork.push(e.prompt);
    return reply === "never" ? new Promise(() => {}) : { value: reply };
  });
  on("ui.toast", (_$, e) => {
    seen.toasts.push(e.text);
    return { value: undefined };
  });
  on("prompt.fill", (_$, e) => {
    seen.fills.push(e.text);
    return { isFilled: true };
  });
  return { seen, clock };
};

const ids = { last: 0 };

/**
 * One real call of `tool` with `input`, as the engine checks it, and then the model call that it starts runs to its end.
 * A query has no `tool_use_id`.
 */
const check = async (
  $: Engine,
  clock: Clock,
  tool: string,
  input: object,
  agentId?: string,
) => {
  const verdict = await $.tool.check({
    tool,
    input,
    tool_use_id: `toolu_${++ids.last}`,
    ...(agentId === undefined ? {} : { agentId }),
  });
  for (let i = 0; i < 5; i++) await clock.advance(0);
  return verdict;
};

const turn = ($: Engine, text: string, turnId: string) =>
  $.turn.start({ text, turnId });

/** The band above the prompt, drawn as the terminal draws it. */
const mountBand = ($: Engine, hasSurvey = false) =>
  $.ui.mount({
    plugin: PLUGIN,
    surface: "terminal",
    component: "AbovePrompt",
    props: {
      hasSurvey,
      isWorking: false,
      maxRows: 20,
      bodyColumns: 80,
      scroll: { offset: 0, bodyRows: 20 },
      view: {},
    },
  });

/** A call of `Edit` through the chain of `tool.call`, with the note context that the plugin adds. */
const callEdit = ($: Engine, agentId?: string) =>
  $.tool.call({
    tool: "Edit",
    ...EDIT,
    ...(agentId === undefined ? {} : { agentId }),
  });

const EDIT = {
  file_path: "/p/src/retry.mjs",
  old_string: "3",
  new_string: "10",
};
const TOPIC =
  "Ten tries with no delay can hit the rate limit of the API faster.";

test("the first changing call of a turn shows the topic in the band", async ($: Engine, on: On) => {
  const { seen, clock } = setup(on, { complete: [answered(TOPIC)] });
  await turn($, "Raise the tries to 10.", "t1");
  expect((await check($, clock, "Edit", EDIT)).decision).toBe("allow");
  expect(seen.toasts).toStrictEqual([]);
  expect(seen.complete[0]).toContain("Raise the tries to 10.");
  expect(seen.complete[0]).toContain("/p/src/retry.mjs");
  expect(seen.fork).toStrictEqual([]);
  const band = await mountBand($);
  expect(
    await band.find({ type: "Text", text: /You should know/ }),
  ).toBeDefined();
  await band.unmount();
});

test("a read gets no check", async ($: Engine, on: On) => {
  const { seen, clock } = setup(on, { complete: [answered(TOPIC)] });
  await turn($, "Look at the file.", "t1");
  await check($, clock, "Bash", { command: "cat src/retry.mjs | head -5" });
  await check($, clock, "Bash", { command: "git log --oneline -3" });
  expect(seen.complete).toStrictEqual([]);
  expect(seen.toasts).toStrictEqual([]);
});

test("a `Bash` call that changes something gets the check", async ($: Engine, on: On) => {
  const { seen, clock } = setup(on, { complete: [answered(TOPIC)] });
  await turn($, "Clean up.", "t1");
  await check($, clock, "Bash", { command: "cat a > b" });
  expect(seen.complete.length).toBe(1);
});

test("a second changing call in the same turn gets no check", async ($: Engine, on: On) => {
  const { seen, clock } = setup(on, {
    complete: [answered("NONE"), answered(TOPIC)],
  });
  await turn($, "Raise the tries.", "t1");
  await check($, clock, "Edit", EDIT);
  await check($, clock, "Write", { file_path: "/p/b.txt", content: "b" });
  expect(seen.complete.length).toBe(1);
  expect(seen.toasts).toStrictEqual([]);
});

